"""Rebuild independent toy fixtures without reading old fixtures or importing the runtime.

The decision model is a six-input toy queue, not a production-policy transcript.
The dispatch model specifies two fictitious routes directly; compile_model is not used.
"""

import json
import pathlib

root = pathlib.Path(__file__).resolve().parents[3]
tests = root / "plugin/tests"


def write(p, x):
    p.write_text(json.dumps(x, ensure_ascii=False, indent=2) + "\n")


# Construct a toy queue decision model from first principles; no readback is an input.
names = {
    "DAYS": "facts.SYNTHETIC.queue_depth",
    "BASIS": "facts.SYNTHETIC.enabled",
    "UNCONFIRMED": "facts.SYNTHETIC.pending",
    "DUPLICATE": "facts.SYNTHETIC.lane",
    "FLAG": "facts.SYNTHETIC.flag",
    "UNUSED": "facts.SYNTHETIC.label",
}
types = {
    "DAYS": "number",
    "BASIS": "boolean",
    "UNCONFIRMED": "boolean",
    "DUPLICATE": "string",
    "FLAG": "boolean",
    "UNUSED": "string",
}


def c(k, op, v):
    return {"path": ["parameters", names[k], "value"], "op": op, "value": v}


def known(k):
    return {"path": ["parameters", names[k], "quality"], "op": "eq", "value": "KNOWN"}


specs = [
    (
        "SYN-LIMIT",
        [known("DAYS"), c("DAYS", "gt", 7), known("BASIS"), c("BASIS", "eq", True)],
        "不成立",
    ),
    ("SYN-LANE", [known("DUPLICATE"), c("DUPLICATE", "eq", "blue")], "不成立"),
    ("SYN-FLAG", [known("FLAG"), c("FLAG", "eq", True)], "不成立"),
    (
        "SYN-READY",
        [known("DAYS"), c("DAYS", "lte", 7), known("UNCONFIRMED"), c("UNCONFIRMED", "eq", False)],
        "成立",
    ),
    ("SYN-FALLBACK", [], "成立"),
]
m = {
    "profile": "service-decision-table-v1",
    "version": "1.0.0",
    "hit_policy": "FIRST",
    "parameters": {
        names[k]: {
            "type": t,
            "record_required": True,
            "nullable": False,
            "allowed_quality": ["KNOWN", "UNKNOWN"],
        }
        for k, t in types.items()
    },
    "rules": [
        {"rule_id": rid, "when": conds, "output_template_ref": rid} for rid, conds, _ in specs
    ],
    "result_templates": {
        rid: {
            "state": state,
            "data": {
                "result": {"literal": ["synthetic", "selected"]},
                "state": {"literal": state},
                "rule_id": {"literal": rid},
            },
            "actions": [],
        }
        for rid, _, state in specs
    },
    "on_no_match": "RESULT_TEMPLATE",
    "empty_template_ref": "synthetic-none",
}
m["result_templates"]["synthetic-none"] = {"state": "NO_MATCH", "data": {}, "actions": []}
write(
    tests / "p2_synthetic_model.json",
    {
        "source": "Independently authored toy queue model; no production readback input. See fixtures/build_independent_models.py.",
        "model_ref": "P2.D1@1.0.0",
        "model": m,
    },
)
# Independent expected routing model for two artificial scenes, not generated by compile_model.
a = "00000000-0000-4000-8000-000000000201"
b = "00000000-0000-4000-8000-000000000202"
rows = [
    ("P_99_01_01", "CONSULT", "STAGE_2", a, "synthetic.alpha"),
    ("P_99_01_02", "FEEDBACK", "STAGE_3", b, "synthetic.beta"),
]
params = {
    k: {"allowed_quality": ["KNOWN"], "nullable": False, "record_required": True, "type": "string"}
    for k in ["scene_id", "issue_type", "phase"]
}


def target(app=None, solution=None):
    routed = app is not None
    state = "routed" if routed else "unregistered"
    data = {
        "route_state": state,
        "route_kind": "SOLUTION_APP" if routed else None,
        "app_id": app,
        "solution_id": solution,
        "kb_refs_json": None,
        "topics_json": None,
        "intents_json": None,
    }
    return {
        "actions": [{"intent_id": "control", "kind": "CONTROL", "route_ref": state}],
        "data": {k: {"literal": v} for k, v in data.items()},
        "state": "ROUTED" if routed else "UNREGISTERED",
    }


model = {
    "profile": "service-decision-table-v1",
    "version": "4.0.0",
    "hit_policy": "FIRST",
    "on_no_match": "RESULT_TEMPLATE",
    "empty_template_ref": "unregistered",
    "parameters": params,
    "result_templates": {"unregistered": target()},
    "rules": [],
}
routes = []
registry = {}
scenes = {}
for sid, issue, phase, app, solution in rows:
    ref = "solution-app:" + app
    model["result_templates"][ref] = target(app, solution)
    model["rules"].append(
        {
            "rule_id": "·".join([sid, issue, phase]),
            "output_template_ref": ref,
            "when": [
                {"op": "eq", "path": ["parameters", k, "value"], "value": v}
                for k, v in [("scene_id", sid), ("issue_type", issue), ("phase", phase)]
            ],
        }
    )
    t = {"kind": "SOLUTION_APP", "app_id": app, "solution_id": solution}
    routes.append({"scene_id": sid, "issue_type": issue, "phase": phase, "target": t})
    registry[sid] = [{"app_id": app, "solution_id": solution}]
    scenes[sid] = {"solutions": [{"app_id": app, "solution_id": solution, "status": "CURRENT"}]}
table = {
    "table": "dispatch.route",
    "issue_types": ["COMPLAINT", "CONSULT", "FEEDBACK"],
    "phases": ["STAGE_1", "STAGE_2", "STAGE_3"],
    "note": "",
    "registry": registry,
    "routes": routes,
}
write(
    tests / "dispatch_synthetic_readback.json",
    {
        "_source": "Independently authored two-scene routing fixture, no captured workflow. Expected model authored without calling compiler.",
        "expected_table": table,
        "published": {
            "id": "00000000-0000-4000-8000-000000000200",
            "graph": {
                "nodes": [
                    {
                        "id": "admission-dmn",
                        "data": {
                            "tool_configurations": {
                                "definition_bundle_json": {
                                    "type": "constant",
                                    "value": json.dumps(
                                        {"models": {"dispatch.route@4.0.0": model}},
                                        ensure_ascii=False,
                                    ),
                                }
                            }
                        },
                    },
                    {
                        "id": "admission-input",
                        "data": {"code": "REGISTRY=" + repr({"scenes": scenes})},
                    },
                ]
            },
        },
    },
)
